from requests.utils import get_encoding_from_headers

def test_get_encoding_crash():
    headers = {"content-type": "text/plain; charset"}
    # This should not crash. It should probably return "ISO-8859-1" (default for text)
    # because the charset parameter is malformed and should be ignored.
    try:
        encoding = get_encoding_from_headers(headers)
        print(f"Encoding: {encoding}")
    except AttributeError as e:
        print(f"Crashed with AttributeError: {e}")
        raise e

if __name__ == \"__main__\":
    test_get_encoding_crash()

